from pathlib import Path
import json,html,re
base=Path(__file__).resolve().parent / 'db'
data=json.loads((base/'schema.json').read_text()); by={t['table']:t for t in data}
core=['Protocolo','MomentoProtocolo','EtapaProtocolo','ProgramacaoProtocolo','ParticipacaoProtocolo','TarefaProtocolo','VinculoTarefaProtocolo','EventoTarefaProtocolo']
def esc(v):return html.escape(str(v))
def fk(t,c):
 return next((k['definition'] for k in t['constraints'] if k['kind']=='f' and re.search(r'FOREIGN KEY \("?'+re.escape(c)+r'"?\)',k['definition'])),None)
def typ(v):
 return v.replace('timestamp(3) without time zone','timestamp(3)').replace('pecuaria."PrecisaoCalendarioProtocolo"','PrecisaoCalendario').replace('pecuaria."TipoProtocolo"','TipoProtocolo').replace('pecuaria."FinalidadeAplicacao"','FinalidadeAplicacao')
def card(name,x,y,fields=None):
 t=by[name];cols=t['columns'] if fields is None else [c for c in t['columns'] if c['name'] in fields]
 cols=sorted(cols,key=lambda c:(c['name']!='id',0 if fk(t,c['name']) else 1))
 rows=''
 for c in cols:
  badge='PK' if c['name']=='id' else 'FK' if fk(t,c['name']) else ''
  rows+=f'<div class="field" title="{esc(fk(t,c["name"]) or c["default"] or "Sem default SQL")}"><span class="key {badge.lower()}">{badge}</span><code>{esc(c["name"])}</code><span class="dtype">{esc(typ(c["type"]))}</span><b class="nullable">{"?" if c["nullable"] else ""}</b></div>'
 return f'<article class="entity {"accent" if name=="TarefaProtocolo" else ""}" style="left:{x}px;top:{y}px;width:430px" id="entity-{name}"><button class="entity-title" data-table="{name}"><small>{esc(t["schema"])} · {"recorte" if fields else str(len(cols))+" colunas"}</small><strong>{name}</strong><span>↗</span></button>{rows}</article>'
# Deterministic rows sized from the catalog: cards never overlap or cut fields.
names=core+['Animal']
positions={}; row_y=60
for start in range(0,len(names),3):
 row=names[start:start+3]
 for col,name in enumerate(row): positions[name]=(40+col*570,row_y)
 row_y+=max(66+26*(3 if name=='Animal' else len(by[name]['columns'])) for name in row)+150
height=row_y
cards=''.join(card(name,*positions[name],['id','brinco','nome'] if name=='Animal' else None) for name in names)
svg=f'<svg width="1680" height="{height}" class="edges" aria-hidden="true"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8" fill="none" stroke="#668b82"/></marker></defs>'
# Every drawn edge is derived from an actual FK, including composite keys.
for name in names:
 x,y=positions[name]
 for k in by[name]['constraints']:
  if k['kind']!='f': continue
  m=re.search(r'REFERENCES (?:[a-z_]+\.)?"([^" ]+)"',k['definition'])
  if not m or m[1] not in positions: continue
  px,py=positions[m[1]]
  col=re.search(r'FOREIGN KEY \((.*?)\)',k['definition'])[1]
  lane=25+len(svg)%55
  svg+=f'<path d="M{px+430} {py+32} H{px+430+lane} V{y+32} H{x}" fill="none" stroke="#668b82" stroke-width="1.5" marker-end="url(#arrow)"/><title>{esc(m[1]+" → "+name+": "+col)}</title>'
svg+='</svg>'
content=r'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>DB · Núcleo de protocolos</title><style>
:root{--ink:#213c36;--muted:#596e67;--border:#cad7d1;--bg:#f1f5f2;--green:#21594b}*{box-sizing:border-box}body{margin:0;background:var(--bg);font:15px/1.55 system-ui,sans-serif;color:var(--ink)}header{padding:17px 28px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;gap:20px;background:white;font-size:13px}.brand{font-weight:750;letter-spacing:1px}main{max-width:1320px;padding:40px 28px 70px;margin:auto}h1{font-size:40px;line-height:1.15;letter-spacing:-1px;margin:10px 0 18px}h2{font-size:24px;margin:0 0 10px;line-height:1.3}h3{font-size:18px;margin:0 0 10px}p{margin:0 0 14px}.lead{font-size:18px;max-width:950px;color:var(--muted)}.eyebrow{font-size:11px;font-weight:750;letter-spacing:1.4px;color:var(--muted);text-transform:uppercase}.bar{border-left:3px solid var(--green);padding:10px 18px;margin:24px 0;background:#e6eee8}.bar p:last-child{margin-bottom:0}nav{display:flex;gap:20px;flex-wrap:wrap;margin:24px 0 32px}a{color:var(--green)}section{scroll-margin-top:20px;margin-top:42px}.small{color:var(--muted);font-size:13px}button,select{font:inherit}button{cursor:pointer}button,select{border:1px solid #a8bbb0;background:white;color:var(--ink);padding:8px 13px;border-radius:6px}button:hover{background:#eaf0e9}button:focus-visible,a:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid #b27c2f;outline-offset:3px}.toolbar{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;padding:16px 18px;background:white;border:1px solid var(--border);border-radius:10px 10px 0 0}.toolbar .buttons{display:flex;gap:6px}.canvas-window{overflow:auto;border:1px solid var(--border);border-top:0;background-color:#edf3f0;background-image:radial-gradient(#b8ccc3 .75px,transparent .75px);background-size:18px 18px;max-height:none}.canvas-sizer{position:relative}.canvas{position:relative;width:1680px;height:__HEIGHT__px;transform-origin:top left}.edges{position:absolute;top:0;left:0;pointer-events:none}.entity{position:absolute;background:white;border:1px solid #a8beb3;border-radius:8px;overflow:hidden;box-shadow:0 4px 12px #1c47350a}.entity.accent{border:2px solid var(--green)}.entity-title{display:block;text-align:left;background:#e6eee8;border:0;border-bottom:1px solid var(--border);border-radius:0;padding:12px 14px;width:100%;height:64px;position:relative}.entity-title small{display:block;font-size:10px;text-transform:uppercase;letter-spacing:1px;color:var(--muted)}.entity-title strong{font-size:17px}.entity-title>span{position:absolute;right:15px;top:24px}.field{height:26px;display:flex;gap:5px;padding:3px 10px;align-items:center;border-bottom:1px solid #edf1ee;font-size:11px;white-space:nowrap}.field:last-child{border:0}.field code{font:12px ui-monospace,SFMono-Regular,monospace;color:#203e34;flex:1}.key{font-size:9px;font-weight:750;width:22px;flex:none}.pk{color:#9b5c0c}.fk{color:#29675a}.dtype{font:10px ui-monospace,monospace;color:#667c73;max-width:154px;text-overflow:ellipsis;overflow:hidden}.nullable{width:7px;color:#9b5c0c}.diagram-note{position:absolute;padding:20px;border:1px dashed #adc0b5;border-radius:8px;width:430px;background:#f8faf7}.diagram-note code{font-size:12px}.diagram-note p{font-size:14px}.legend{display:flex;gap:22px;flex-wrap:wrap;font-size:12px;color:var(--muted);margin:12px 0}.panel{background:white;border:1px solid var(--border);border-radius:10px;overflow:hidden}.twocol{display:grid;grid-template-columns:1fr 1fr;gap:20px}.pad{padding:23px}.table-scroll{overflow:auto}table{width:100%;border-collapse:collapse;text-align:left;font-size:13px}th{font-weight:650;background:#edf3ee;color:var(--muted);font-size:12px}td,th{padding:11px 14px;border-bottom:1px solid #dce5df;vertical-align:top}tr:last-child td{border-bottom:0}code{font:13px/1.55 ui-monospace,SFMono-Regular,monospace;overflow-wrap:anywhere}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f3f6f3;padding:16px;border-radius:6px;font:12px/1.65 ui-monospace,monospace;margin:12px 0}.pager{display:flex;gap:12px;justify-content:space-between;align-items:center;padding:14px 18px;border-top:1px solid var(--border);font-size:13px}.pager>div{display:flex;gap:7px}.pager button:disabled{opacity:.4;cursor:default}.tag{font-size:11px;font-weight:650;padding:4px 7px;background:#e5eee4;border-radius:4px;display:inline-block}.warn{background:#fbf2e3;border-left:3px solid #bb8842;padding:16px 20px;font-size:14px;margin-top:20px}.inspector-head{display:flex;align-items:end;justify-content:space-between;gap:20px;padding:18px;border-bottom:1px solid var(--border)}label{display:block;font-size:12px;color:var(--muted);margin-bottom:5px}select{max-width:100%}.constraints{padding:20px}.constraints details{border-top:1px solid var(--border);padding:13px 0}.constraints summary{cursor:pointer;font-weight:650}.constraint-list{max-height:400px;overflow:auto}.empty{color:var(--muted);padding:12px 0}.query{margin-top:22px}.mini-flow{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:16px 0}.mini-flow span{padding:9px 13px;background:#e6eee8;border:1px solid #b4c8bb;border-radius:5px;font:12px ui-monospace,monospace}.links-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.fact-card{padding:15px;background:white;border:1px solid var(--border);border-radius:8px}.fact-card button{width:100%;font-size:13px;font-weight:650;text-align:left}.fact-card p{font-size:12px;margin:12px 0 0}footer{font-size:12px;color:var(--muted);margin-top:40px;border-top:1px solid var(--border);padding-top:20px}@media(max-width:760px){main{padding:28px 16px}header{padding:14px 16px}h1{font-size:31px}.twocol,.links-grid{grid-template-columns:1fr}.inspector-head{align-items:start;flex-direction:column}.table-scroll table{min-width:620px}.canvas-window{max-height:none}.toolbar .small{max-width:100%}}@media print{.canvas-window{max-height:none;overflow:visible}.toolbar .buttons,nav{display:none}.panel,section{break-inside:avoid}}
</style></head><body><header><span class="brand">TERRANO / DB</span><span>PostgreSQL · schemas pecuaria e public · 21/10/2026</span></header><main><div class="eyebrow">Estrutura física inspecionada em somente leitura</div><h1>O banco por trás dos protocolos</h1><p class="lead">Oito tabelas formam o núcleo comum sanitário e reprodutivo. A versão está em <code>Protocolo</code>; a inclusão do animal, em <code>ParticipacaoProtocolo</code>; a tarefa individual, em <code>TarefaProtocolo</code>.</p><div class="bar"><p><strong>Núcleo implementado.</strong> Este diagrama descreve a estrutura encontrada em <code>fazendinha_seedatev3</code>, cruzada com Prisma e migrations: oito tabelas centrais, incluindo o histórico de eventos, e a origem do calendário na participação. Nenhum registro operacional foi consultado.</p></div><nav><a href="../index.html">Base documental</a><a href="../../../plano-acoes-protocolos.md">Registro da entrega local</a><a href="#erd">Diagrama físico</a><a href="#dictionary">Todas as colunas</a><a href="#version">Versão</a><a href="#individual">Tarefa individual</a><a href="#facts">Vínculos com fatos</a><a href="#limits">Garantias SQL</a></nav>
<section id="erd"><h2>1. Diagrama de tabelas e chaves</h2><p class="small">Todas as colunas das oito tabelas centrais estão nos blocos. <code>Animal</code> aparece em recorte. Clique no título de uma tabela para abrir seu catálogo completo. As setas vão da tabela referenciada para a tabela que contém a FK.</p><div class="toolbar"><span><strong>Núcleo compartilhado</strong> <span class="small"> · nomes físicos do PostgreSQL</span></span><div class="buttons"><button id="fit">Ajustar largura</button><button id="zoom-out" aria-label="Diminuir diagrama">−</button><span id="zoom-label" style="align-self:center">100%</span><button id="zoom-in" aria-label="Ampliar diagrama">+</button></div></div><div class="canvas-window" id="viewport" tabindex="0" aria-label="Diagrama de banco com rolagem horizontal"><div class="canvas-sizer" id="sizer"><div class="canvas" id="canvas">__DIAGRAM__</div></div></div><div class="legend"><span><b>PK</b> chave primária</span><span><b>FK</b> chave estrangeira</span><span><b>?</b> aceita NULL</span><span>Seta: tabela referenciada → tabela com FK; destinos externos ao desenho estão no catálogo.</span></div></section>
<section id="dictionary"><h2>2. Catálogo completo de colunas</h2><p class="small">22 tabelas: oito centrais e 14 de apoio (incluindo Animal em recorte no desenho). Tipos, nulabilidade, defaults, constraints, índices e triggers extraídos do catálogo PostgreSQL. Colunas paginadas em até 10 por página. As tabelas de apoio também podem ser selecionadas.</p><div class="panel"><div class="inspector-head"><div><label for="table-select">Tabela física (pecuaria ou public)</label><select id="table-select"></select></div><span class="tag" id="column-count"></span></div><div class="table-scroll"><table><thead><tr><th>Coluna física</th><th>Tipo PostgreSQL</th><th>NULL?</th><th>Default SQL / FK</th></tr></thead><tbody id="columns"></tbody></table></div><div class="pager"><span id="page-label"></span><div><button id="prev">Anterior</button><button id="next">Próxima</button></div></div><div class="constraints"><details><summary>Constraints SQL da tabela</summary><div class="constraint-list" id="constraints"></div></details><details><summary>Índices, incluindo unicidade parcial</summary><div class="constraint-list" id="indexes"></div></details><details><summary>Triggers e funções de proteção</summary><div class="constraint-list" id="triggers"></div></details></div></div><p class="small" style="margin-top:12px">Um default SQL ausente não significa que a aplicação deixe o campo vazio. Por exemplo, IDs de várias tabelas são <code>text</code>, preenchidos com UUID pelo Prisma; não são colunas do tipo PostgreSQL <code>uuid</code>. Relações Prisma como <code>tarefas[]</code> não são colunas físicas.</p></section>
<section id="version"><h2>3. Uma linha de Protocolo já é uma versão</h2><div class="twocol"><div class="panel pad"><h3>Não existe uma tabela ProtocoloVersao</h3><p><code>Protocolo.id</code> identifica a versão exata. <code>versao</code> é o número apresentado, não a chave usada pelas FKs.</p><pre>UNIQUE (tipo, nome, versao)

EtapaProtocolo.protocoloId
ProgramacaoProtocolo.protocoloId
ParticipacaoProtocolo.protocoloId
               ↓
          Protocolo.id</pre><p class="small">Não há coluna <code>familiaId</code> nem FK <code>versaoAnteriorId</code> em Protocolo. O agrupamento atual de versões usa tipo + nome. <code>referenciaTecnica</code> é JSONB, não uma FK de linhagem.</p></div><div class="panel"><div class="pad"><h3>Exemplo de linhas · IDs abreviados</h3><p class="small">Dados didáticos, não extraídos dos animais do banco.</p></div><table><thead><tr><th>id</th><th>nome</th><th>versao</th><th>tipo</th></tr></thead><tbody><tr><td>P1</td><td>IATF X</td><td>1</td><td>REPRODUTIVO</td></tr><tr><td>P2</td><td>IATF X</td><td>2</td><td>REPRODUTIVO</td></tr></tbody></table><div class="pad"><p>Etapas E1 e E2 referenciam P1. Uma nova versão P2 recebe suas próprias linhas de etapas.</p><p>A participação antiga continua com <code>protocoloId = P1</code>. Ela não passa a usar P2 ao consultar a “última versão”.</p></div></div></div></section>
<section id="individual"><h2>4. Inclusão do animal e geração de tarefas</h2><div class="mini-flow"><span>Animal.id</span>→<span>ParticipacaoProtocolo.animalId</span>→<span>TarefaProtocolo.participacaoId</span></div><p>A participação liga um animal a uma versão. <code>programacaoId</code> preenchido reúne essa participação ao coletivo; <code>NULL</code> permite execução individual. A inclusão gera registros de tarefa por etapa, por escrita da aplicação. <strong>Não há trigger no banco que faça essa multiplicação automaticamente.</strong></p><div class="twocol"><div class="panel"><div class="pad"><h3>ParticipacaoProtocolo</h3></div><table><thead><tr><th>id</th><th>animalId</th><th>protocoloId</th><th>programacaoId</th></tr></thead><tbody><tr><td>PA</td><td>A</td><td>P1</td><td>G1</td></tr><tr><td>PB</td><td>B</td><td>P1</td><td>G1</td></tr><tr><td>PC</td><td>C</td><td>P1</td><td>NULL</td></tr></tbody></table><div class="pad small">A e B estão no mesmo coletivo. C recebe a mesma versão individualmente. As três participações são independentes.</div></div><div class="panel"><div class="pad"><h3>TarefaProtocolo</h3></div><table><thead><tr><th>id</th><th>participacaoId</th><th>etapaId</th><th>realizadaEm</th></tr></thead><tbody><tr><td>TA1</td><td>PA</td><td>E1</td><td>21/10/2026</td></tr><tr><td>TA2</td><td>PA</td><td>E2</td><td>NULL</td></tr><tr><td>TB1</td><td>PB</td><td>E1</td><td>NULL</td></tr><tr><td>TB2</td><td>PB</td><td>E2</td><td>NULL</td></tr><tr><td>TC1</td><td>PC</td><td>E1</td><td>NULL</td></tr><tr><td>TC2</td><td>PC</td><td>E2</td><td>NULL</td></tr></tbody></table></div></div><div class="bar"><p><strong>3 participações × 2 etapas = 6 linhas em TarefaProtocolo.</strong> Registrar <code>realizadaEm</code> em TA1 não altera E1 nem realiza TB1 ou TC1. O planejamento individual fica em <code>previstaEm</code> e <code>planejadoSnapshot</code>; a execução, em <code>realizadaEm</code>, <code>realizadoSnapshot</code> e nos fatos vinculados.</p></div><div class="query"><h3>O JOIN que revela os dois contextos</h3><pre>SELECT t.id AS tarefa_id,
       a.id AS animal_id,
       p.id AS participacao_id,
       p."programacaoId",
       v.id AS protocolo_id, v.nome, v.versao,
       e.id AS etapa_id, e.ordem,
       t."previstaEm", t."realizadaEm"
FROM pecuaria."TarefaProtocolo" t
JOIN pecuaria."ParticipacaoProtocolo" p ON p.id = t."participacaoId"
JOIN pecuaria."Animal" a ON a.id = p."animalId"
JOIN pecuaria."Protocolo" v ON v.id = p."protocoloId"
JOIN pecuaria."EtapaProtocolo" e
  ON e.id = t."etapaId" AND e."protocoloId" = v.id
ORDER BY p.id, e.ordem
LIMIT 10 OFFSET 0;</pre><p class="small">Consulta ilustrativa, não executada. A paginação limita as linhas lidas; não muda os relacionamentos.</p></div></section>
<section id="facts"><h2>5. Onde a tarefa se conecta ao atendimento</h2><p><code>VinculoTarefaProtocolo</code> guarda o histórico dos vínculos. Cada linha aponta para exatamente um fato: aplicação, exame, tentativa ou manejo. O fato também conserva sua FK <code>tarefaId</code>, que é opcional para fatos fora de protocolo.</p><div class="panel pad"><div class="mini-flow"><span>TarefaProtocolo.id</span>1 → 0..N<span>VinculoTarefaProtocolo.tarefaId</span></div><pre>VinculoTarefaProtocolo.aplicacaoId  → AplicacaoProduto.id
VinculoTarefaProtocolo.exameId      → ExameAnimal.id
VinculoTarefaProtocolo.tentativaId  → TentativaReprodutiva.id
VinculoTarefaProtocolo.manejoId     → ManejoAnimal.id

CHECK num_nonnulls(aplicacaoId, exameId, tentativaId, manejoId) = 1
UNIQUE (tarefaId, ordem)
UNIQUE (tarefaId) WHERE estado = 'ATUAL'</pre><p class="small">As quatro FKs do vínculo aceitam NULL individualmente; o CHECK exige exatamente uma preenchida. Podem existir vários vínculos históricos, mas no máximo um ATUAL por tarefa. Manejo e retirada são fatos individuais; manejoId integra a mesma exclusividade dos outros três tipos de fato.</p></div><div class="links-grid" style="margin-top:18px"><div class="fact-card"><button data-table="AplicacaoProduto">AplicacaoProduto ↗</button><p><code>id · animalId · tarefaId</code><br>Fato de aplicação, produtos e consumo.</p></div><div class="fact-card"><button data-table="ExameAnimal">ExameAnimal ↗</button><p><code>id · animalId · tarefaId</code><br>Fato de exame e seus resultados.</p></div><div class="fact-card"><button data-table="TentativaReprodutiva">TentativaReprodutiva ↗</button><p><code>id · animalId · tarefaId</code><br>Fato da tentativa reprodutiva.</p></div></div><div class="panel pad" style="margin-top:18px"><h3>Extensão reprodutiva: FKs até a gestação</h3><pre>ExameAnimal.id  ← InterpretacaoReprodutiva.exameId [UNIQUE]
TentativaReprodutiva.id ← InterpretacaoReprodutiva.tentativaId [NULL]
GestacaoAnimal.id ← InterpretacaoReprodutiva.gestacaoId [NULL]

Animal.id ← GestacaoAnimal.animalId
TentativaReprodutiva.id ← GestacaoAnimal.tentativaId [NULL, UNIQUE]</pre><p class="small">Um exame tem no máximo uma interpretação reprodutiva; uma gestação pode ser referenciada por várias interpretações. Não há FK direta de GestacaoAnimal para Protocolo: a rastreabilidade passa pelos fatos e suas tarefas. Abra essas tabelas no catálogo para ver todas as colunas.</p></div></section>
<section id="limits"><h2>6. O que o SQL garante</h2><div class="panel table-scroll"><table><thead><tr><th>Objeto</th><th>Garantia verificada</th></tr></thead><tbody><tr><td><code>Protocolo_tipo_nome_versao_key</code></td><td>Unicidade da combinação tipo, nome e número de versão.</td></tr><tr><td><code>Protocolo_versao</code> e <code>EtapaProtocolo_imutavel</code></td><td>Protegem campos estruturais da versão publicada/usada e etapas publicadas/usadas contra as alterações cobertas pelos triggers.</td></tr><tr><td><code>ParticipacaoProtocolo_contexto</code></td><td>Exige versão compatível com a programação e sítio compatível quando informado. Impede trocar a versão de uma participação que já tem tarefas.</td></tr><tr><td>Índice parcial de participação ativa</td><td>Impede duas participações não canceladas do mesmo animal na mesma programação. Participações individuais, com programacaoId NULL, não entram nesse índice.</td></tr><tr><td>Unique da tarefa + <code>TarefaProtocolo_versao</code></td><td>Uma tarefa por participação/etapa. A etapa e a participação devem apontar para o mesmo protocoloId.</td></tr><tr><td><code>VinculoTarefaProtocolo_fato</code></td><td>Confere o animal, o tipo da etapa, a tarefa do fato e a validade do fato para um vínculo ATUAL.</td></tr><tr><td><code>EventoTarefaProtocolo_formato_check</code> e <code>EventoTarefaProtocolo_validar</code></td><td>Validam combinação de campos e retificação contra evento anterior da mesma tarefa; o trigger recusa UPDATE do evento.</td></tr></tbody></table></div><div class="warn"><strong>Limite importante do schema:</strong> FKs e triggers validam as linhas escritas; não garantem, sozinhos, que toda etapa recebeu uma tarefa, nem selecionam os animais automaticamente. Também não existe uma coluna <code>status</code> em TarefaProtocolo: a representação de “pendente”, “atendido” e demais estados precisa respeitar os campos e fatos existentes. “Não atendido” é um evento operacional separado de <code>dispensadaEm</code>; não representa fato clínico nem status persistido na tarefa.</div></section>
<section><h2>7. Banco físico ≠ nome da propriedade Prisma</h2><div class="panel"><table><thead><tr><th>Tabela</th><th>Coluna física mostrada aqui</th><th>Propriedade Prisma</th></tr></thead><tbody><tr><td>EtapaProtocolo</td><td><code>intervalo</code></td><td><code>diaRelativo</code></td></tr><tr><td>ParticipacaoProtocolo</td><td><code>programacaoId</code></td><td><code>rodadaId</code></td></tr><tr><td>ParticipacaoProtocolo</td><td><code>inicioReferencia</code></td><td><code>inicio</code></td></tr><tr><td>TarefaProtocolo</td><td><code>participacaoId</code></td><td><code>execucaoId</code></td></tr><tr><td>TarefaProtocolo</td><td><code>previstaEm</code></td><td><code>previstaPara</code></td></tr><tr><td>TarefaProtocolo</td><td><code>planejadoSnapshot</code></td><td><code>parametros</code></td></tr><tr><td>TarefaProtocolo</td><td><code>motivo</code></td><td><code>motivoDispensa</code></td></tr></tbody></table></div></section>
<section><h2>Momentos, fatos e acompanhamento</h2><p><code>MomentoProtocolo</code> organiza ações da versão. Cada <code>EtapaProtocolo</code> continua gerando uma tarefa própria por animal; duas ações em D0 são independentes. A geração ocorre no serviço, sem trigger multiplicadora. Versões usadas preservam suas ações e snapshots.</p><p><code>MANEJO</code> possui fato em <code>ManejoAnimal</code> e classificação própria. Retirada referencia a inserção; <code>AplicacaoProduto.insercaoSnapshot</code> conserva o contexto em JSONB. Referências dentro de snapshots não representam novas entidades ou FKs.</p><p><code>DemandaAcompanhamentoReprodutivo</code> admite prazo ausente somente na origem <code>PROTOCOLO</code>. Origem de exame e reavaliação são rastreadas pela demanda. Exame sem resultado não equivale a negativo, nem <code>NAO_REALIZADO</code> equivale a atendimento.</p><p>Custos, estoque e gestação têm tabelas e FKs próprias no catálogo completo. Referências estimadas ficam em <code>EtapaProtocolo.configuracao.referenciasCusto</code> e <code>TarefaProtocolo.planejadoSnapshot</code>: material (valorUnitario, unidade, origem, data) e serviço (unidade POR_ATENDIMENTO). São JSONB, não fatos financeiros. O realizado agrega fontes sem duplicá-las; confirmação coletiva de até 100 animais é atômica. Listas são apresentadas em páginas de até dez.</p><p><strong>Implementação local em validação.</strong> Estes metadados de estrutura não comprovam dados, interface, revisão final, CI ou homologação.</p></section><footer>Fotografia de 21/10/2026. Fonte primária: pg_catalog do PostgreSQL local fazendinha_seedatev3, consultado com default_transaction_read_only=on. Cruzamento: server/prisma/schema.prisma e migrations de protocolos comuns. Apenas metadados exportados; nenhum dado de animais consultado neste levantamento. <a href="schema.json" download>Baixar metadados SQL das 22 tabelas (8 centrais + 14 de apoio)</a>.</footer></main>
<script>const catalog=__CATALOG__;let chosen='TarefaProtocolo',page=0,zoom=.7;const escapeHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const select=document.getElementById('table-select');const order=catalog.map(t=>t.table);select.innerHTML=catalog.map(t=>`<option value="${t.table}">${t.schema}.${t.table}</option>`).join('');const objectPages={constraints:0,indexes:0,triggers:0};function render(){const t=catalog.find(t=>t.table===chosen);select.value=chosen;document.getElementById('column-count').textContent=t.columns.length+' colunas físicas';document.getElementById('columns').innerHTML=t.columns.slice(page*10,page*10+10).map(c=>{let fk=t.constraints.find(k=>k.kind==='f'&&k.definition.startsWith('FOREIGN KEY ("'+c.name+'")'));let pk=t.constraints.find(k=>k.kind==='p'&&k.definition.includes('('+c.name+')'));return `<tr><td><code>${escapeHtml(c.name)}</code> ${pk?'<span class="tag">PK</span>':fk?'<span class="tag">FK</span>':''}</td><td><code>${escapeHtml(c.type)}</code></td><td>${c.nullable?'Sim':'Não'}</td><td><code>${escapeHtml(c.default??'Sem default SQL')}</code>${fk?'<br><code>'+escapeHtml(fk.definition)+'</code>':''}</td></tr>`}).join('');document.getElementById('page-label').textContent=`Colunas ${page*10+1}–${Math.min(page*10+10,t.columns.length)} de ${t.columns.length} · Página ${page+1} de ${Math.ceil(t.columns.length/10)}`;document.getElementById('prev').disabled=page===0;document.getElementById('next').disabled=(page+1)*10>=t.columns.length;for(const kind of ['constraints','indexes','triggers'])renderObjects(kind,t);}
function renderObjects(kind,t){const list=t[kind],n=objectPages[kind],root=document.getElementById(kind);root.innerHTML=list.length?list.slice(n*10,n*10+10).map(k=>`<p><code>${escapeHtml(k.name)}</code></p><pre>${escapeHtml(k.definition)}${k.function?'\n\n'+escapeHtml(k.function):''}</pre>`).join(''):'<p class="empty">Nenhum objeto deste tipo.</p>';if(list.length>10){const bar=document.createElement('div');bar.className='pager';bar.innerHTML=`<span>Página ${n+1} de ${Math.ceil(list.length/10)}</span><div><button ${n===0?'disabled':''}>Anterior</button><button ${(n+1)*10>=list.length?'disabled':''}>Próxima</button></div>`;bar.querySelectorAll('button').forEach((b,i)=>b.onclick=()=>{objectPages[kind]+=i?1:-1;renderObjects(kind,t);root.scrollTop=0});root.appendChild(bar);}}
function choose(n){chosen=n;page=0;Object.keys(objectPages).forEach(k=>objectPages[k]=0);render();document.getElementById('dictionary').scrollIntoView({block:'start'});}document.querySelectorAll('[data-table]').forEach(b=>b.addEventListener('click',()=>choose(b.dataset.table)));select.addEventListener('change',()=>{chosen=select.value;page=0;Object.keys(objectPages).forEach(k=>objectPages[k]=0);render()});document.getElementById('prev').onclick=()=>{page--;render()};document.getElementById('next').onclick=()=>{page++;render()};function scale(){document.getElementById('canvas').style.transform=`scale(${zoom})`;document.getElementById('sizer').style.width=1680*zoom+'px';document.getElementById('sizer').style.height=__HEIGHT__*zoom+'px';document.getElementById('zoom-label').textContent=Math.round(zoom*100)+'%';}document.getElementById('fit').onclick=()=>{zoom=Math.min(1,document.getElementById('viewport').clientWidth/1680);scale()};document.getElementById('zoom-in').onclick=()=>{zoom=Math.min(1.5,zoom+.1);scale()};document.getElementById('zoom-out').onclick=()=>{zoom=Math.max(.3,zoom-.1);scale()};zoom=Math.min(1,Math.max(.65,document.getElementById('viewport').clientWidth/1680));scale();render();</script></body></html>'''
relations=''.join('<details><summary>'+esc(t['schema']+'.'+t['table'])+'</summary>'+''.join('<pre>'+esc(k['definition'])+'</pre>' for k in t['constraints'] if k['kind']=='f')+'</details>' for t in data)
content=content.replace('<section id="dictionary">','<section><h2>Relações físicas das 22 tabelas</h2><p>Inventário exato de FKs do catálogo; inclusive custos, estoque, gestação e relações externas ao desenho central. Ausência de FK não é uma relação implícita.</p>'+relations+'</section><section id="dictionary">')
content=content.replace('__HEIGHT__',str(height)).replace('__DIAGRAM__',svg+cards).replace('__CATALOG__',json.dumps(data,ensure_ascii=False).replace('</','<\\/'))
(base/'index.html').write_text(content)
print(base/'index.html')
